using System.Text.RegularExpressions;
using Haruspex.Diagnostics;
using Haruspex.Ir;

namespace Haruspex.Tests.Config;

/// <summary>
/// A column's schema generated by the pinned Zod's <c>z.toJSONSchema</c>, as a team that keeps its Zod schema as the source
/// would generate it (<c>tests/emit-check/src/zod-to-json-schema.mjs</c>): every keyword Zod emits is read, or is a warning and
/// read wider, never an error.
/// </summary>
public partial class ColumnDeclarationTests
{
    /// <summary>The keywords Zod 4.6.7 emits for the invented schema that haruspex doesn't check, each a warning.</summary>
    private static readonly string[] ZodKeywordsNotChecked = ["format", "maximum", "minimum", "pattern", "propertyNames"];

    [Fact]
    public void A_schema_zod_generates_is_read_with_a_warning_for_each_keyword_not_checked_and_no_error()
    {
        EmitCheckPackage.RequireNode(RepositoryPaths.EmitCheck, "the schema Zod generates was not read");
        EmitCheckPackage.EnsureInstalled(RepositoryPaths.EmitCheck);
        Assert.True(EmitCheckPackage.TryRun("node", [Path.Combine("src", "zod-to-json-schema.mjs")], RepositoryPaths.EmitCheck, out var schema, out var why), why);
        using var dir = new TempDirectory();
        dir.File("schemas/settings.schema.json", schema);

        var read = Read(dir);

        Assert.All(read.Diagnostics, d => Assert.Equal(DiagnosticSeverity.Warning, d.Code.Severity));
        Assert.Equal(ZodKeywordsNotChecked, read.Diagnostics.Select(d => Regex.Match(Assert.IsType<JsonLocation>(d.At).Path, @"\w+$").Value).Distinct().Order(StringComparer.Ordinal));
        var declared = Assert.Single(read.Expected().Columns);
        Assert.Equal(["fast", "slow"], Assert.IsType<IrScalar>(Field(declared, "mode").Type).Facets?.Values?.Items.Select(v => v.Text));
        Assert.Equal((IrPresence.Optional, 1), (Field(declared, "note").Presence, Assert.IsType<IrScalar>(Field(declared, "note").Type).Facets?.MinLength?.Value));
        Assert.True(Field(declared, "contact").Nullable);
        Assert.Equal(new IrRecord(new IrScalar(IrScalarKind.Number, null, null), []), Field(declared, "tags").Type);
        Assert.Equal(
            [["courier"], ["pickup"]],
            Assert.IsType<IrUnion>(Field(declared, "delivery").Type).Variants
                .Select(v => Assert.IsType<IrScalar>(Fields(declared, v).Single(f => f.Name == "kind").Type).Facets?.Values?.Items.Select(i => i.Text).ToArray()));
        Assert.Equal(1, Assert.IsType<IrArray>(Field(declared, "lines").Type).MinItems);
    }
}
